{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/0"],
      "relevance": "상담사가 '늘'이 얼마나 오래된 건지 물은 것은 정서적 결핍 스키마가 만성적으로 작동해 온 기간을 추적하려는 질문이다. 내담자가 '늘 그랬으니까'라고 답한 것은 이 결핍이 오래전부터 자기 삶의 기본 조건이 되어 있었음을 보여준다."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "'늘 그랬으니까'라는 답변은 '마음을 알아주기를 바라는 것은 애초에 이루어지지 않는 일'이라는 핵심 신념이 내담자에게 당연한 전제로 자리 잡고 있음을 보여준다. 상담사가 이 신념의 기원을 거슬러 올라가려 하고 있다."
    },
    {
      "trait_id": "/core_belief/schema_definition",
      "background_ids": ["/childhood_data", "/situations/0"],
      "relevance": "'결핍 자체를 자각하지 못한 채 만성 공허감으로 경험'이라는 정의가 내담자의 '이런 걸 말해도 되는 건지 모르겠어요', '아무 일도 아닌데'라는 표현과 정확히 대응한다. 상담사가 이 무자각 상태를 언어화하려 하고 있다."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/0"],
      "relevance": "'힘든 것은 혼자 처리해야 한다'는 규칙이 눈물이 차오를 때 주방으로 가서 혼자 서 있는 행동으로 나타난다. 상담사가 그 순간의 마음을 물은 것은 이 규칙이 작동하는 장면을 함께 들여다보기 위함이다."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_positive",
      "background_ids": ["/childhood_data"],
      "relevance": "'아무것도 기대하지 않고 내 몫을 조용히 해내면 무난하게 살 수 있다'는 가정이 '늘 그랬으니까'라는 답에 압축되어 있다. 상담사가 '늘'의 시간을 물은 것은 이 가정이 언제부터, 어떤 조건에서 형성되었는지 확인하려는 것이다."
    },
    {
      "trait_id": "/coping_strategies/4",
      "background_ids": ["/situations/0"],
      "relevance": "내담자가 '물 마시고 올게 하고 주방으로 가서 좀 서 있다가 와요'라고 말한 것은 '아무도 없는 곳에서 소리 없이 울고 나와 스스로를 나무람'이라는 대처 방식과 일치한다. '내가 이상한 건가'라는 자책도 이 전략의 일부이다."
    }
  ]
}

